<script setup>import {ref,computed} from 'vue';import AppShell from '../../components/AppShell.vue';import {workOrders} from '../../api/mock';const order=workOrders[0],good=ref(48),defect=ref(1),operation=ref('扭矩锁付'),submitted=ref(false);const total=computed(()=>Number(good.value)+Number(defect.value));function submit(){submitted.value=true;setTimeout(()=>submitted.value=false,2600)}</script>
<template><AppShell mode="shopfloor"><div class="page-head"><div><span class="breadcrumb">生产执行 / 生产报工</span><h1>工序报工</h1><p>记录本次合格产量、不良数量和生产工时。</p></div><router-link class="secondary" to="/shopfloor">返回工作台</router-link></div><div v-if="submitted" class="success-toast">✓ 报工已提交，工单进度已更新</div><div class="report-layout"><section class="panel report-form"><div class="report-order"><div><span>生产工单</span><b>{{order.no}}</b><small>{{order.product}} · 批次 {{order.batch}}</small></div><div class="remaining"><span>剩余数量</span><strong>{{(order.plan-order.done).toLocaleString()}}</strong><small>件</small></div></div><div class="form-section"><h2>本次报工</h2><div class="form-grid"><label><span>工序</span><select v-model="operation"><option>扭矩锁付</option><option>部件装配</option><option>功能测试</option></select></label><label><span>操作工</span><input value="徐明远" disabled/></label><label class="quantity good"><span>合格数量</span><div><button @click="good=Math.max(0,good-1)">−</button><input v-model.number="good" type="number"/><button @click="good++">＋</button></div></label><label class="quantity defect"><span>不良数量</span><div><button @click="defect=Math.max(0,defect-1)">−</button><input v-model.number="defect" type="number"/><button @click="defect++">＋</button></div></label><label><span>开始时间</span><input value="2026-07-29 13:42"/></label><label><span>结束时间</span><input value="2026-07-29 14:20"/></label><label class="full-field"><span>备注</span><textarea placeholder="可填写停机、返修或物料情况"></textarea></label></div></div><div class="report-submit"><div><span>本次投入</span><b>{{total}} 件</b><small>提交后将写入工单实绩与在制追溯记录</small></div><button class="primary" @click="submit">确认提交报工</button></div></section><div class="report-aside"><section class="panel"><div class="panel-head"><div><h2>工艺控制点</h2><p>扭矩锁付 · OP30</p></div></div><dl class="spec-list"><div><dt>锁付扭矩</dt><dd>2.8 ± 0.2 N·m</dd></div><div><dt>程序版本</dt><dd>AX120-TQ-V3.2</dd></div><div><dt>抽检频次</dt><dd>每 50 件 / 次</dd></div><div><dt>防错校验</dt><dd class="ok">已启用</dd></div></dl></section><section class="panel"><div class="panel-head"><div><h2>本班累计</h2><p>08:00 至当前</p></div></div><div class="shift-total"><div><b>864</b><span>合格数量</span></div><div><b>12</b><span>不良数量</span></div><div><b>98.6%</b><span>一次合格率</span></div><div><b>12.4s</b><span>平均节拍</span></div></div></section></div></div></AppShell></template>
